export function freshState(){return {version:1,active:null,profiles:[],settings:{sound:true,duration:10},session:null}}
export function loadState(storage){try{const s=JSON.parse(storage.getItem('taman-main-v1'));if(s?.version!==1||!Array.isArray(s.profiles))return freshState();s.profiles=s.profiles.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&['preschool','kindergarten'].includes(p.level)&&p.progress&&typeof p.progress==='object').map(p=>({...p,name:p.name.slice(0,24),avatar:['🐰','🐻','🐱','🐼','🦊','🐸'].includes(p.avatar)?p.avatar:'🐰',stories:Array.isArray(p.stories)?p.stories.filter(id=>stories.some(b=>b.id===id)):[],progress:Object.fromEntries(Object.entries(p.progress).filter(([id,r])=>activities.some(a=>a.id===id)&&r&&Number.isInteger(r.runs)&&r.runs>0&&Number.isInteger(r.independent)&&r.independent>=0))}));s.settings={sound:typeof s.settings?.sound==='boolean'?s.settings.sound:true,duration:[5,10,15].includes(s.settings?.duration)?s.settings.duration:10};if(!s.profiles.some(p=>p.id===s.active))s.active=s.profiles[0]?.id??null;const q=s.session;const p=s.profiles.find(p=>p.id===s.active);if(!q||q.profile!==s.active||!Array.isArray(q.ids)||q.ids.length!==3||!q.ids.every(id=>activities.some(a=>a.id===id&&a.level===p?.level))||!Number.isInteger(q.index)||q.index<0||q.index>2||!Number.isFinite(q.started))s.session=null;return s}catch{return freshState()}}
export function saveState(storage,state){try{storage.setItem('taman-main-v1',JSON.stringify(state));return true}catch{return false}}
export function addProfile(state,name,level,avatar){const id=globalThis.crypto?.randomUUID?.()??`p-${Date.now()}-${Math.random()}`;state.profiles.push({id,name:name.trim().slice(0,24)||'Little friend',level,avatar,progress:{},stories:[]});state.active=id;state.session=null;return id}
export function activeProfile(state){return state.profiles.find(p=>p.id===state.active)}
export function complete(state,id,attempts){const p=activeProfile(state);if(!p)return;const prev=p.progress[id]??{runs:0,independent:0};p.progress[id]={runs:prev.runs+1,independent:attempts===1?prev.independent+1:0,last:Date.now()}}
export function label(p){return !p?'Just explored':p.independent>=2?'Growing confident':'Still practicing'}
export function recommend(state){const p=activeProfile(state);if(!p)return [];return activities.filter(a=>a.level===p.level).sort((a,b)=>{const score=x=>{const r=p.progress[x.id];return r?(r.independent<2?0:2):1};return score(a)-score(b)}).slice(0,3)}
